/**
 * Convert VideoFrame to ImageData for zxing-wasm.
 *
 * zxing-wasm requires ImageData, but VideoFrame is more efficient.
 * This conversion is necessary but adds overhead.
 */
async function videoFrameToImageData(frame: VideoFrame, roi?: ROI): Promise<ImageData> {
  // Create an ImageBitmap from the VideoFrame
  const bitmap = await createImageBitmap(frame);

  // Draw to a canvas to get ImageData
  const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
  const ctx = canvas.getContext('2d');
  if (!ctx) {
    throw new Error('Failed to get 2D context from OffscreenCanvas');
  }

  ctx.drawImage(bitmap, 0, 0);

  // Apply ROI crop if specified
  if (roi) {
    const imageData = ctx.getImageData(roi.x, roi.y, roi.w, roi.h);
    bitmap.close();
    return imageData;
  }

  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

  // Close the bitmap to free memory
  bitmap.close();

  return imageData;
}

